#include "WifiManager.h"
#include "Config.h"
void WifiManager::begin(){WiFi.persistent(false);WiFi.mode(WIFI_AP_STA);WiFi.setSleep(false);WiFi.softAP(Config::AP_SSID,Config::AP_PASSWORD,Config::AP_CHANNEL,false,Config::AP_MAX_CLIENTS);_stationConfigured=!Config::settings.staSsid.isEmpty();if(_stationConfigured)connectStation();Serial.println("================================");Serial.println(" SMART RADAR STATION");Serial.println("================================");Serial.println();Serial.println("WiFi iniciado");Serial.printf("SSID: %s\n",Config::AP_SSID);Serial.printf("IP: %s\n",WiFi.softAPIP().toString().c_str());Serial.println();Serial.println("Sistema pronto.");}void WifiManager::connectStation(){_stationConfigured=!Config::settings.staSsid.isEmpty();_lastStationAttemptMs=millis();if(!_stationConfigured){WiFi.disconnect(false,false);return;}Serial.printf("[WiFi] Conectando à rede externa: %s\n",Config::settings.staSsid.c_str());WiFi.begin(Config::settings.staSsid.c_str(),Config::settings.staPassword.c_str());}void WifiManager::requestStationReconnect(){_reconnectRequested=true;}void WifiManager::update(){if(_reconnectRequested){_reconnectRequested=false;WiFi.disconnect(false,false);connectStation();return;}_stationConfigured=!Config::settings.staSsid.isEmpty();if(!_stationConfigured||stationConnected())return;if(millis()-_lastStationAttemptMs>=Config::WIFI_RETRY_MS)connectStation();}int16_t WifiManager::rssi()const{return stationConnected()?static_cast<int16_t>(WiFi.RSSI()):0;}String WifiManager::apIp()const{return WiFi.softAPIP().toString();}String WifiManager::stationIp()const{return stationConnected()?WiFi.localIP().toString():String("-");}uint8_t WifiManager::apClients()const{return static_cast<uint8_t>(WiFi.softAPgetStationNum());}
